import{_ as r,C as o,o as i,c as l,ag as a,E as n}from"./chunks/framework.DUTPmUpA.js";const s="/_assets/YearlyDismalHuemul.CG5qltU4.mp4",b=JSON.parse('{"title":"Начиная","description":"","frontmatter":{"title":"Начиная","author":"Myll","steamId":"76561198000729788","date":"22.02.2015"},"headers":[],"relativePath":"getting-started.md","filePath":"getting-started.md"}'),p={name:"getting-started.md"};function c(h,e,d,m,u,_){const t=o("StaticVideo");return i(),l("div",null,[e[0]||(e[0]=a('<h2 id="_015" tabindex="-1">015 <a class="header-anchor" href="#_015" aria-label="Permalink to &quot;015&quot;">​</a></h2><h1 id="начало-работы" tabindex="-1">Начало работы <a class="header-anchor" href="#начало-работы" aria-label="Permalink to &quot;Начало работы&quot;">​</a></h1><p>Итак, вы новичок в моддинге Dota 2? Не знаете, с чего, черт возьми, начать? Это руководство для тебя, будущего моддера Dota 2!</p><p>Примечание. «Аддон», «мод» и «пользовательская игра» являются синонимами в этом руководстве (и, вероятно, на всем веб-сайте).</p><h2 id="аспекты-моддинга-dota-2" tabindex="-1">Аспекты моддинга Dota 2 <a class="header-anchor" href="#аспекты-моддинга-dota-2" aria-label="Permalink to &quot;Аспекты моддинга Dota 2&quot;">​</a></h2><p><a href="https://developer.valvesoftware.com/wiki/Dota_2_Workshop_Tools" target="_blank" rel="noreferrer">Workshop Tools Wiki Homepage</a> хорошо справляется с разделением всех возможных аспектов моддинга Dota 2:</p><ul><li><strong>Дизайн уровней</strong> - Использует инструмент под названием «Молот».</li><li><strong>Сценарии</strong> — подразделяются на редактирование KeyValue и сценарии Lua.</li><li><strong>Моделирование</strong> - Импорт ваших собственных моделей в аддон.</li><li><strong>Звуки</strong> - Импорт собственных звуков или редактирование существующих.</li><li><strong>Частицы</strong> – редактирование существующих частиц или создание собственных с помощью инструмента редактирования частиц (PET).</li><li><strong>Панорама</strong> — Создание собственного пользовательского интерфейса или изменение существующего пользовательского интерфейса Dota 2 с помощью скриптов Panorama.</li></ul><h2 id="шаг-0-установка-и-запуск-инструментов-мастерскои-dota-2" tabindex="-1">Шаг 0. Установка и запуск инструментов мастерской Dota 2 <a class="header-anchor" href="#шаг-0-установка-и-запуск-инструментов-мастерскои-dota-2" aria-label="Permalink to &quot;Шаг 0. Установка и запуск инструментов мастерской Dota 2&quot;">​</a></h2><p>Вы не сможете создавать моды для Dota без инструментов Мастерской!</p><p>взято из <a href="https://developer.valvesoftware.com/wiki/Dota_2_Workshop_Tools/Installing_and_Launching_Tools" target="_blank" rel="noreferrer">How to install the Dota 2 Workshop Tools</a>:</p><ul><li>Щелкните правой кнопкой мыши Dota 2 в Steam и выберите «Просмотреть загружаемый контент».</li><li>Установите флажок в столбце «Установить» рядом с DLC «Dota 2 Workshop Tools».</li><li>Нажмите «Закрыть». Начнется загрузка необходимого контента.</li><li>Когда загрузка будет завершена, запустите Dota 2 в Steam и выберите «Запустить Dota 2 — Инструменты».</li></ul><h2 id="шаг-1-создание-нового-аддона-из-шаблона" tabindex="-1">Шаг 1. Создание нового аддона из шаблона <a class="header-anchor" href="#шаг-1-создание-нового-аддона-из-шаблона" aria-label="Permalink to &quot;Шаг 1. Создание нового аддона из шаблона&quot;">​</a></h2><p>Чтобы начать с хорошего, вам нужно создать новое дополнение на основе шаблона. У вас есть два варианта на выбор:</p><h3 id="вариант-1-шаблон-дополнения-typescript" tabindex="-1">Вариант 1: Шаблон дополнения TypeScript <a class="header-anchor" href="#вариант-1-шаблон-дополнения-typescript" aria-label="Permalink to &quot;Вариант 1: Шаблон дополнения TypeScript&quot;">​</a></h3><p>Содержит:</p><ul><li>Объявления типов API Dota 2, которые помогут вам с проверкой ошибок и автозаполнением вашего кода.</li><li>Пример правил игры</li><li>Пример возможности TypeScript</li><li>Пример модификатора TypeScript — Пример пользовательского интерфейса Panorama с TypeScript.</li><li>Скрипт автоматической установки</li><li>Библиотека последних таймеров</li></ul><p>Этот шаблон содержит все, что вам нужно для создания модов с помощью TypeScript. Dota 2 использует Lua в качестве языка сценариев, поэтому этот шаблон включает инструменты для автоматического перевода TypeScript в Lua. Он обеспечивает основу для разработки дополнений, но кроме этого содержит лишь несколько небольших примеров. Он поставляется с автоматической настройкой контроля версий git «из коробки».</p><p>Чтобы начать работу с шаблоном TypeScript, см. <a href="https://github.com/ModDota/TypeScriptAddonTemplate" target="_blank" rel="noreferrer">The template GitHub page</a> и <a href="./scripting/Typescript/typescript-introduction">TypeScript introduction</a> для ознакомления с шаблоном и инструкциями по установке.</p><h3 id="вариант-2-шаблон-barebones-lua" tabindex="-1">Вариант 2: Шаблон Barebones Lua <a class="header-anchor" href="#вариант-2-шаблон-barebones-lua" aria-label="Permalink to &quot;Вариант 2: Шаблон Barebones Lua&quot;">​</a></h3><p>Содержит:</p><ul><li>Некоторые правила игры и настройки по умолчанию, которые вы можете легко настроить.</li><li>Пример способностей Lua</li><li>Примеры модификаторов Lua</li><li>Некоторые старые библиотеки, такие как <code>animations</code>, <code>physics</code>, <code>projectiles</code> и <code>timers</code>.</li></ul><p>Вы можете начать работу с шаблона Barebones, который является созданной сообществом альтернативой стандартным шаблонам дополнений Valve (например, Holdout). Это ссылка на обновленные Barebones: <a href="https://github.com/DarkoniusXNG/barebones" target="_blank" rel="noreferrer">https://github.com/DarkoniusXNG/barebones</a><br> После загрузки его в виде zip-архива вы хотите перейти к <code>.../Steam/SteamApps/dota 2 beta/</code> и объединить папки <code>game</code> и <code>content</code> из .zip в эту папку /dota 2 beta/ (в которой уже должны быть папки с именами <code>game</code> и <code>content</code>). Затем запустите инструменты мастерской (или перезапустите их, если они уже открыты) и дважды щелкните новое дополнение. Установите его как аддон по умолчанию. Затем перейдите в Hammer -&gt; Файл -&gt; Открыть -&gt; <code>template_map.vmap</code> -&gt; Нажмите F9, чтобы начать создание карты. После того, как Хаммер завершит создание вашей карты, ваша собственная игра автоматически загрузится в Dota.</p><h2 id="шаг-2-создание-карты-в-hammer" tabindex="-1">Шаг 2. Создание карты в Hammer <a class="header-anchor" href="#шаг-2-создание-карты-в-hammer" aria-label="Permalink to &quot;Шаг 2. Создание карты в Hammer&quot;">​</a></h2>',23)),n(t,{path:s}),e[1]||(e[1]=a('<p>(Спасибо DarkMio за этот gfy.)</p><p>Hammer — это инструмент, который вы используете для создания миров для вашей собственной игры. Я настоятельно рекомендую вам сначала начать создавать что-то в Hammer, а не сразу погружаться в сценарии или другой аспект. У вас могут быть самые сложные сценарии в мастерской, но как люди будут получать удовольствие от вашей игры, если не существует мира, в котором они могли бы играть?</p><p>Как только вы дойдете до того, что для вашей карты будет заблокирован черновой макет, вероятно, можно будет безопасно перейти к написанию сценариев. Вы не хотите тратить слишком много времени на детализацию того, что, как вы понимаете, необходимо изменить, как только вы войдете в суть своего режима. <a href="https://developer.valvesoftware.com/wiki/Dota_2_Workshop_Tools/Level_Design" target="_blank" rel="noreferrer">The wiki page on Hammer</a> хорошо знакомит вас с Hammer. Я бы рекомендовал вам начать с раздела <a href="https://developer.valvesoftware.com/wiki/Dota_2_Workshop_Tools/Level_Design/Tile_Editor_Basics" target="_blank" rel="noreferrer">Tile editor</a>.</p><p>BMD подготовила несколько неплохих обучающих видеороликов по Hammer для начинающих:</p><ul><li><a href="https://www.youtube.com/watch?v=GMvmdnNM6Sc" target="_blank" rel="noreferrer">Part 1: Tile Editor</a></li><li><a href="https://www.youtube.com/watch?v=grLUv2hUDRY" target="_blank" rel="noreferrer">Part 2: Mesh Basics</a></li><li><a href="https://www.youtube.com/watch?v=ln3ep-k__dk" target="_blank" rel="noreferrer">Part 3: Entity Basics</a></li></ul><h2 id="шаг-3-создание-сценариев-и-не-только" tabindex="-1">Шаг 3. Создание сценариев и не только... <a class="header-anchor" href="#шаг-3-создание-сценариев-и-не-только" aria-label="Permalink to &quot;Шаг 3. Создание сценариев и не только...&quot;">​</a></h2><p>Сценарии — следующая по важности часть вашего аддона. Он разделен на сценарии Lua и сценарии KeyValue. Я собираюсь перенаправить вас на <a href="./scripting-introduction">Noya&#39;s Beginner Scripting Guide</a>, так как там содержится по сути та же информация, что и в этом разделе. Теперь я буду говорить коротко и по делу. Я уже предоставил вам массу информации, чтобы вы могли начать углубляться в моддинг Dota 2! Если вы хорошо разбираетесь в картографии Hammer и сценариях Lua и KeyValue, это поможет создавать успешные и увлекательные пользовательские игры Dota 2. Пожалуйста, не стесняйтесь задавать вопросы в <a href="https://t.me/+4wTdvuzBPzUxOTgy" target="_blank" rel="noreferrer">Telegram-канале ModdotaRU</a>.</p><h2 id="дополнительные-ресурсы" tabindex="-1">Дополнительные ресурсы <a class="header-anchor" href="#дополнительные-ресурсы" aria-label="Permalink to &quot;Дополнительные ресурсы&quot;">​</a></h2><p>Темы Source 2, выходящие за рамки модификаций пользовательских игр Dota 2, можно найти на <a href="https://www.source2.wiki/" target="_blank" rel="noreferrer">source2.wiki</a>. Он охватывает более широкий спектр информации о движке Source 2 и может содержать более актуальную документацию по общим функциям Source 2.</p>',9))])}const f=r(p,[["render",c]]);export{b as __pageData,f as default};
